package consts

//SliceLiteralConst is generated by optimizer of ArrayLiteral
// NOTE: can't change this const, copy it when write to
type SliceLiteralConst struct {
	Value []any
	Name  string
}

// MapLiteralConst is generated by optimizer of DictLiteral
// NOTE: can't change this const, copy it when write to
type MapLiteralConst struct {
	Map  map[ConstNode]*ConstNode
	Name string
}

type FunctionConst struct {
	Name       string
	ParamCount int
	LocalCount int
	Addr       int // 函数入口地址, 在[]AllFuncs中的索引
	Code       []StackInstr
}

type StructConst struct {
	Name   string
	Fields []string
}
